/***
 * MARK: System settings tabs
 * @description Single source of truth for the System Settings section tabs:
 *   id, label, and whether the settings footer's Reset control applies. The
 *   Notifications and UI panels persist immediately through their own
 *   controls (each with its own reset), so the footer Reset — which only
 *   restores the settings draft (+ Storage remount) — would be a misleading
 *   no-op there and is hidden. Every consumer (the SystemSettingsPage screen,
 *   SystemSettingsContent, unit tests, and the canary tab-bar suite) derives
 *   from this list so a new tab can never drift the expectations again.
 * @example SETTINGS_TABS.find((t) => t.id === 'ui') => { id: 'ui', label: 'UI', showFooterReset: false }
 ***/

export const SETTINGS_TABS = [
  { id: 'runners', label: 'Runners', showFooterReset: true },
  { id: 'models', label: 'Models', showFooterReset: true },
  { id: 'engine', label: 'Engine', showFooterReset: true },
  { id: 'storage', label: 'Storage', showFooterReset: true },
  { id: 'notifications', label: 'Notifications', showFooterReset: false },
  { id: 'prompt-layout', label: 'Prompt Layout', showFooterReset: false },
  { id: 'ui', label: 'UI', showFooterReset: false },
];

/***
 * MARK: SETTINGS_TAB_LABELS
 * @description Ordered tab labels derived from SETTINGS_TABS (render order).
 * @example SETTINGS_TAB_LABELS => ['Harness', 'Models', 'Engine', 'Storage', 'Notifications', 'UI']
 ***/
export const SETTINGS_TAB_LABELS = SETTINGS_TABS.map((tab) => tab.label);

/***
 * MARK: isFooterResetVisible
 * @description Whether the settings footer Reset applies to a section id.
 *   Unknown ids fail open (true) so a future tab without metadata keeps the
 *   legacy behaviour instead of silently losing its reset.
 * @example isFooterResetVisible('ui') => false
 * @param {string} sectionId - Active section id.
 * @returns {boolean} True when the footer Reset should render.
 ***/
export function isFooterResetVisible(sectionId) {
  if (typeof sectionId !== 'string' || !sectionId) return true;
  const tab = SETTINGS_TABS.find((entry) => entry.id === sectionId);
  if (!tab) return true;
  return tab.showFooterReset !== false;
}

import React, { useState } from 'react';
import { Icon } from '../Icon';
import { FALLBACK_MODELS } from '../stageTypes';
import { useModelCatalog } from '../../hooks/useModelCatalog';
import { useModelRefreshSetting } from '../../hooks/useModelRefreshSetting';

import { RunnerConfigurationSection } from './RunnerConfigurationSection';
import { StorageSection } from './StorageSection';
import { PushNotificationsSection } from './PushNotificationsSection';
import { PromptLayoutSection } from './PromptLayoutSection';
import { UiPreferencesPanel } from './UiPreferencesPanel';
import { MODEL_REFRESH_CONFIG_KEY } from './modelRefreshFlag';
import { SETTINGS_TABS, isFooterResetVisible } from './settingsTabs';

export const SYSTEM_SETTINGS_SECTIONS = SETTINGS_TABS.map(({ id, label }) => ({ id, label }));

export const DEFAULT_SYSTEM_SETTINGS_DRAFT = {
  stageTimeoutSecs: 600,
  allowPermissionBypass: false,
  defaultModel: '',
  fallbackModel: '',
  maxConcurrentTasks: 1,
  autoAdvanceStages: true,
  startComputeOnBoot: false,
};

/***
 * MARK: SettingRow
 * @description Label + control row used by the System Settings wireframe.
 * @example <SettingRow label="Default model" hint="..."><input /></SettingRow>
 ***/
export function SettingRow({ label, hint, children }) {
  return (
    <div className="flex flex-col gap-1.5 py-3 border-b border-border-standard last:border-b-0">
      <span className="text-xs font-bold text-on-surface">{label}</span>
      {children}
      {hint && <span className="text-[11px] text-text-muted">{hint}</span>}
    </div>
  );
}

/***
 * MARK: SystemSettingsContent
 * @description Route- and shell-agnostic System Settings content component.
 * Renders header, tablist, all section panels (Runners, Models, Engine, Storage,
 * Notifications, Prompt Layout, UI), and footer actions. Rendered by the
 * standalone SystemSettingsPage screen (`/system-settings`); it takes no
 * modal state and never renders a dialog shell.
 * @param {Object} props
 * @param {string} [props.activeSection] - Controlled active tab id (e.g. from route).
 * @param {Function} [props.onSectionChange] - Callback when tab changes: (sectionId) => void.
 * @param {Function} [props.onClose] - Close callback (close button and Done button). The page leaves this unset and navigates via onBack instead.
 * @param {Function} [props.onBack] - Back callback (page back button and Done button fallback).
 * @param {string} [props.backLabel='Back to Board'] - Visible/accessible label for the back affordance. The page swaps it to "Close window" inside a popout.
 * @param {'h1'|'h2'} [props.headingLevel='h2'] - Level for the "System Settings" title.
 ***/
export function SystemSettingsContent({
  activeSection: controlledSection,
  onSectionChange,
  onClose,
  onBack,
  backLabel = 'Back to Board',
  headingLevel = 'h2',
}) {
  const [internalActiveSection, setInternalActiveSection] = useState('runners');
  const activeSection = controlledSection ?? internalActiveSection;

  const setActiveSection = (sectionId) => {
    setInternalActiveSection(sectionId);
    onSectionChange?.(sectionId);
  };

  const [draft, setDraft] = useState(DEFAULT_SYSTEM_SETTINGS_DRAFT);

  // Live config gate and shared model catalogue hooks are enabled whenever this
  // content component is mounted.
  const { enabled: modelRefreshEnabled } = useModelRefreshSetting(true);
  const {
    models,
    harnesses,
    refreshing: modelsRefreshing,
    refresh: refreshModels,
  } = useModelCatalog(FALLBACK_MODELS, { enabled: true });

  const [storageResetKey, setStorageResetKey] = useState(0);

  const update = (key, value) => setDraft((prev) => ({ ...prev, [key]: value }));
  const resetDraft = () => {
    setDraft(DEFAULT_SYSTEM_SETTINGS_DRAFT);
    setStorageResetKey((prev) => prev + 1);
  };

  const handleDone = () => {
    if (onClose) {
      onClose();
    } else if (onBack) {
      onBack();
    }
  };

  // Fail-safe section resolution: an unknown id falls back to the first tab.
  const effectiveSection = SYSTEM_SETTINGS_SECTIONS.some((section) => section.id === activeSection)
    ? activeSection
    : SYSTEM_SETTINGS_SECTIONS[0].id;

  const isDraftOnlySection = effectiveSection === 'models' || effectiveSection === 'engine';

  const showReset = isFooterResetVisible(effectiveSection);

  const inputClass =
    'w-full max-w-sm p-2 bg-surface-deep border border-border-standard rounded-sm text-sm text-on-surface outline-none focus:border-primary transition-colors';
  const toggleClass = 'flex items-center gap-2 cursor-pointer select-none text-xs text-on-surface';

  const HeadingTag = headingLevel === 'h1' ? 'h1' : 'h2';

  return (
    <>
      <header className="px-4 sm:px-6 py-3.5 sm:py-4 border-b border-border-standard bg-surface flex items-center justify-between shrink-0">
        <div className="flex items-center gap-3 min-w-0">
          {onBack && (
            <button
              type="button"
              onClick={onBack}
              aria-label={backLabel}
              className="px-3 py-1.5 min-h-[44px] bg-surface hover:bg-surface-container-high border border-border-standard rounded text-xs font-mono font-bold uppercase text-on-surface hover:text-primary transition-colors cursor-pointer flex items-center gap-1.5 shrink-0"
            >
              <span>←</span>
              <span>{backLabel}</span>
            </button>
          )}
          <div className="flex items-center gap-2 min-w-0">
            <span className="text-primary text-base select-none" aria-hidden="true">
              ⚙️
            </span>
            <HeadingTag
              id="system-settings-title"
              className="text-xs sm:text-sm font-bold uppercase tracking-wider text-on-surface font-label-caps truncate"
            >
              System Settings
            </HeadingTag>
          </div>
        </div>
        {onClose && (
          <button
            type="button"
            onClick={onClose}
            className="p-1 min-h-[44px] min-w-[44px] hover:bg-surface-container-high rounded text-text-muted hover:text-on-surface transition-colors flex items-center justify-center cursor-pointer shrink-0"
            aria-label="Close system settings"
          >
            <Icon name="close" />
          </button>
        )}
      </header>

      {/* shrink-0 invariant: bar never shrinks, the details pane scrolls */}
      <div
        role="tablist"
        aria-label="System settings sections"
        className="flex gap-1 px-4 sm:px-6 pt-3 bg-surface border-b border-border-standard overflow-x-auto shrink-0"
      >
        {SYSTEM_SETTINGS_SECTIONS.map((section) => (
          <button
            key={section.id}
            type="button"
            role="tab"
            aria-selected={effectiveSection === section.id}
            onClick={() => setActiveSection(section.id)}
            className={`px-3 py-2 min-h-[44px] text-xs font-bold uppercase tracking-wider rounded-t-sm transition-colors cursor-pointer whitespace-nowrap ${
              effectiveSection === section.id
                ? 'text-primary border-b-2 border-primary bg-surface-container-high'
                : 'text-text-muted hover:text-on-surface'
            }`}
          >
            {section.label}
          </button>
        ))}
      </div>

      <div className="flex-1 min-h-0 overflow-y-auto px-4 sm:px-6 py-2 custom-scrollbar bg-surface-deep">
        {isDraftOnlySection && (
          <p
            id="system-settings-wireframe-note"
            className="mt-3 px-3 py-2 text-[11px] font-mono text-text-muted bg-surface-container-high border border-border-standard rounded-sm"
          >
            Wireframe — changes here are not saved yet. Backend persistence lands in a later stage.
          </p>
        )}

        {effectiveSection === 'runners' && (
          <div role="tabpanel" aria-label="Runner settings">
            <RunnerConfigurationSection />
          </div>
        )}

        {effectiveSection === 'models' && (
          <div role="tabpanel" aria-label="Model settings">
            <div
              data-testid="model-catalogue"
              className="flex flex-col gap-2 py-3 border-b border-border-standard"
            >
              <span className="text-xs font-bold text-on-surface">Discovered models</span>
              <p data-testid="model-catalogue-count" className="text-[11px] text-text-muted">
                {models.length} models across {harnesses.length} harnesses in the shared catalogue.
              </p>
              {modelRefreshEnabled && (
                <button
                  type="button"
                  onClick={() => void refreshModels()}
                  disabled={modelsRefreshing}
                  className="self-start px-3 py-1.5 min-h-[44px] bg-surface-container-high hover:bg-surface-container-highest disabled:opacity-50 text-on-surface-variant text-[11px] font-bold uppercase tracking-widest rounded-sm transition-colors cursor-pointer disabled:cursor-default"
                >
                  {modelsRefreshing ? 'Refreshing…' : 'Refresh models'}
                </button>
              )}
              {!modelRefreshEnabled && (
                <p
                  data-testid="model-refresh-disabled-note"
                  className="text-[11px] text-text-muted"
                >
                  Model refresh is disabled by the {MODEL_REFRESH_CONFIG_KEY} setting.
                </p>
              )}
            </div>
            <SettingRow
              label="Default model"
              hint="Model reference for new stages, e.g. harness::provider::id."
            >
              <input
                type="text"
                aria-label="Default model"
                placeholder="e.g. pi::ollama-cloud::glm-5.3-flash"
                value={draft.defaultModel}
                onChange={(e) => update('defaultModel', e.target.value)}
                className={inputClass}
              />
            </SettingRow>
            <SettingRow label="Fallback model" hint="Used when the default model is unavailable.">
              <input
                type="text"
                aria-label="Fallback model"
                placeholder="e.g. pi::ollama-cloud::glm-4.6"
                value={draft.fallbackModel}
                onChange={(e) => update('fallbackModel', e.target.value)}
                className={inputClass}
              />
            </SettingRow>
          </div>
        )}

        {effectiveSection === 'engine' && (
          <div role="tabpanel" aria-label="Engine settings">
            <SettingRow
              label="Max concurrent tasks"
              hint="How many tasks the compute engine may run at once."
            >
              <input
                type="number"
                aria-label="Max concurrent tasks"
                min={1}
                max={16}
                value={draft.maxConcurrentTasks}
                onChange={(e) => update('maxConcurrentTasks', Number(e.target.value))}
                className={inputClass}
              />
            </SettingRow>
            <SettingRow label="Stage flow" hint="Advance stages automatically when gates pass.">
              <label className={toggleClass}>
                <input
                  type="checkbox"
                  checked={draft.autoAdvanceStages}
                  onChange={(e) => update('autoAdvanceStages', e.target.checked)}
                  className="rounded-sm bg-surface-deep border-border-standard text-primary focus:ring-0 cursor-pointer"
                />
                <span>Auto-advance stages</span>
              </label>
            </SettingRow>
            <SettingRow label="Boot behaviour" hint="Start the compute engine when the app boots.">
              <label className={toggleClass}>
                <input
                  type="checkbox"
                  checked={draft.startComputeOnBoot}
                  onChange={(e) => update('startComputeOnBoot', e.target.checked)}
                  className="rounded-sm bg-surface-deep border-border-standard text-primary focus:ring-0 cursor-pointer"
                />
                <span>Start compute on boot</span>
              </label>
            </SettingRow>
          </div>
        )}

        {effectiveSection === 'storage' && (
          <div role="tabpanel" aria-label="Storage settings">
            <StorageSection key={storageResetKey} />
          </div>
        )}

        {effectiveSection === 'notifications' && (
          <div role="tabpanel" aria-label="Notification settings">
            <PushNotificationsSection />
          </div>
        )}

        {effectiveSection === 'prompt-layout' && (
          <div role="tabpanel" aria-label="Prompt Layout settings">
            <PromptLayoutSection />
          </div>
        )}

        {effectiveSection === 'ui' && (
          <div role="tabpanel" aria-label="UI settings">
            <UiPreferencesPanel onOpenPushNotifications={() => setActiveSection('notifications')} />
          </div>
        )}
      </div>

      <footer className="px-4 sm:px-6 py-3 border-t border-border-standard bg-surface flex justify-between items-center gap-2 shrink-0">
        {showReset ? (
          <button
            type="button"
            onClick={resetDraft}
            className="px-4 py-2 min-h-[44px] bg-surface-container-high hover:bg-surface-container-highest text-on-surface-variant text-xs font-bold uppercase tracking-widest rounded-sm transition-colors cursor-pointer"
          >
            Reset
          </button>
        ) : (
          <span className="text-[11px] text-text-muted">
            Changes save automatically in this section.
          </span>
        )}
        <button
          type="button"
          onClick={handleDone}
          className="px-6 py-2 min-h-[44px] bg-primary text-on-primary text-xs font-bold uppercase tracking-widest rounded-sm hover:brightness-110 transition-all active:scale-95 cursor-pointer"
        >
          Done
        </button>
      </footer>
    </>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { api } from '../../services/api';
import { copyToClipboard } from '../../services/clipboard';
import { formatRunnerElapsed } from '../observability/widgets/PerRunnerTasksWidget';
import {
  defaultRunnerConfig,
  runnerDisplayName,
  advertisedToolIds,
  effectiveTools,
  loadedProjectIds,
  partitionProjects,
  withProjectLoaded,
  withProjectUnloaded,
  scopePatchForLoaded,
  validateDirectories,
  jobTypeLabels,
} from './runnerConfigHelpers';

const DirectoryField = ({
  label,
  testId,
  value,
  error,
  busy,
  confirmArmed,
  onChange,
  onSave,
}) => (
  <div className="flex flex-col gap-1">
    <label className="text-xs font-bold text-on-surface" htmlFor={`${testId}-input`}>
      {label}
    </label>
    <div className="flex items-center gap-2">
      <input
        id={`${testId}-input`}
        type="text"
        data-testid={testId}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className="flex-1 min-w-0 p-2 bg-surface-deep border border-border-standard rounded-sm text-sm text-on-surface outline-none focus:border-primary transition-colors"
      />
      <button
        type="button"
        data-testid={`${testId}-save`}
        onClick={onSave}
        disabled={busy}
        className="px-3 py-2 min-h-[44px] bg-surface-container-high hover:bg-surface-container-highest text-on-surface-variant text-xs font-bold uppercase tracking-widest rounded-sm transition-colors cursor-pointer disabled:opacity-60 shrink-0"
      >
        {confirmArmed ? 'Sure?' : 'Save'}
      </button>
    </div>
    {confirmArmed && (
      <p className="text-[11px] text-warning" data-testid={`${testId}-confirm`}>
        This changes where the Runner reads and writes. Click Save again to confirm.
      </p>
    )}
    {error && (
      <p className="text-[11px] text-error" role="alert" data-testid={`${testId}-error`}>
        {error}
      </p>
    )}
  </div>
);

/***
 * MARK: RunnerConfigurationSection
 * @description System Settings › Runners › detailed Runner configuration
 *   (replaces the legacy harness on/off list): a roster of Runner
 *   registrations with approve/deny for join requests and pause/resume/
 *   revoke for active Runners, plus a configuration form for the selected
 *   Runner — display name, Available/Loaded project picker, available-tool
 *   checkboxes, Master/Worktree directory editors with save confirmation,
 *   and Runs CI / Runs merges / Runs Impromptu switches. Operator choices
 *   persist per Runner via `PATCH /runners/:id/config` and heartbeats never
 *   overwrite them. Credential values are never rendered (the approve
 *   response carries the single one-time copy).
 * @example <RunnerConfigurationSection />
 ***/
export function RunnerConfigurationSection() {
  const [runners, setRunners] = useState(null);
  const [projects, setProjects] = useState(null);
  const [assignments, setAssignments] = useState({});
  const [scheduler, setScheduler] = useState(null);
  const [selectedId, setSelectedId] = useState(null);
  const [loadError, setLoadError] = useState(null);
  const [projectsError, setProjectsError] = useState(null);
  const [busyKey, setBusyKey] = useState(null);
  const [actionError, setActionError] = useState(null);
  const [notice, setNotice] = useState(null);
  const [freshCredential, setFreshCredential] = useState(null);
  const [copied, setCopied] = useState(false);
  const [nameDrafts, setNameDrafts] = useState({});
  const [dirDrafts, setDirDrafts] = useState({});
  const [dirConfirm, setDirConfirm] = useState(null);
  const [dirErrors, setDirErrors] = useState({});
  const [nowMs, setNowMs] = useState(null);

  const loadRunners = useCallback(async () => {
    setLoadError(null);
    try {
      const list = await api.getRunners();
      const rows = Array.isArray(list) ? list : [];
      setRunners(rows);
      setSelectedId((prev) => {
        if (prev && rows.some((r) => r.runnerId === prev)) return prev;
        return rows.length > 0 ? rows[0].runnerId : null;
      });
      try {
        const monitor = await api.getRunnerMonitor();
        const byRunner = {};
        for (const row of monitor?.liveAssignments || []) {
          if (row && typeof row.runnerId === 'string') byRunner[row.runnerId] = row;
        }
        setAssignments(byRunner);
        setScheduler(monitor?.scheduler || null);
        setNowMs(Date.now());
      } catch {
        setAssignments({});
        setScheduler(null);
      }
      try {
        const fetched = await api.listProjects();
        setProjects(Array.isArray(fetched) ? fetched : fetched?.projects || []);
        setProjectsError(null);
      } catch {
        setProjects([]);
        setProjectsError('Could not load projects — the picker is unavailable.');
      }
    } catch (err) {
      setRunners(null);
      setLoadError(err?.message || 'Could not load Runner registrations.');
    }
  }, []);

  useEffect(() => {
    void Promise.resolve().then(() => loadRunners());
  }, [loadRunners]);

  const mutate = useCallback(
    async (runnerId, action) => {
      const key = `${action}:${runnerId}`;
      setBusyKey(key);
      setActionError(null);
      setNotice(null);
      try {
        if (action === 'approve') {
          const res = await api.approveRunner(runnerId);
          if (res?.credential) {
            setFreshCredential({ runnerId, credential: res.credential });
            setCopied(false);
          }
        } else if (action === 'deny') await api.denyRunner(runnerId);
        else if (action === 'pause') await api.pauseRunner(runnerId);
        else if (action === 'resume') await api.resumeRunner(runnerId);
        else await api.revokeRunner(runnerId);
        await loadRunners();
      } catch (err) {
        setActionError(err?.message || `Could not ${action} Runner ${runnerId}.`);
      } finally {
        setBusyKey(null);
      }
    },
    [loadRunners],
  );

  const saveConfig = useCallback(
    async (runnerId, patch, successNote) => {
      const key = `config:${runnerId}:${Object.keys(patch).join('+')}`;
      setBusyKey(key);
      setActionError(null);
      try {
        const updated = await api.updateRunnerConfig(runnerId, patch);
        const nextConfig = updated?.operatorConfig || defaultRunnerConfig(updated || {});
        setRunners((prev) =>
          Array.isArray(prev)
            ? prev.map((r) =>
                r.runnerId === runnerId ? { ...r, operatorConfig: nextConfig } : r,
              )
            : prev,
        );
        if (successNote) setNotice(successNote);
        return true;
      } catch (err) {
        setActionError(err?.message || `Could not save Runner ${runnerId} settings.`);
        return false;
      } finally {
        setBusyKey(null);
      }
    },
    [],
  );

  const reloadSelected = useCallback(async () => {
    if (!selectedId) return;
    setBusyKey(`reload:${selectedId}`);
    setActionError(null);
    try {
      const record = await api.getRunnerConfig(selectedId);
      const nextConfig = record?.operatorConfig || defaultRunnerConfig(record || {});
      setRunners((prev) =>
        Array.isArray(prev)
          ? prev.map((r) =>
              r.runnerId === selectedId ? { ...r, ...record, operatorConfig: nextConfig } : r,
            )
          : prev,
      );
      setNameDrafts((prev) => {
        const next = { ...prev };
        // eslint-disable-next-line security/detect-object-injection -- key is the selected Runner id
        delete next[selectedId];
        return next;
      });
      setDirDrafts((prev) => {
        const next = { ...prev };
        // eslint-disable-next-line security/detect-object-injection -- key is the selected Runner id
        delete next[selectedId];
        return next;
      });
      setDirConfirm(null);
      setNotice('Reloaded Runner settings from the backend.');
    } catch (err) {
      setActionError(err?.message || `Could not reload Runner ${selectedId}.`);
    } finally {
      setBusyKey(null);
    }
  }, [selectedId]);

  if (runners === null && !loadError) {
    return (
      <div className="py-6 text-xs text-text-muted" data-testid="runner-config-loading">
        Loading Runner registrations…
      </div>
    );
  }

  if (loadError) {
    return (
      <div className="py-6 flex flex-col gap-3" data-testid="runner-config-error">
        <p className="text-xs text-text-muted">{loadError}</p>
        <button
          type="button"
          onClick={loadRunners}
          className="self-start px-4 py-2 min-h-[44px] bg-surface-container-high hover:bg-surface-container-highest text-on-surface-variant text-xs font-bold uppercase tracking-widest rounded-sm transition-colors cursor-pointer"
        >
          Retry
        </button>
      </div>
    );
  }

  const selected = runners.find((r) => r.runnerId === selectedId) || null;
  const pending = runners.filter((r) => r.status === 'pending');
  const config = selected ? defaultRunnerConfig(selected) : null;
  const loadedIds = selected ? loadedProjectIds(selected, projects || []) : [];
  const { available, loaded } = partitionProjects(projects || [], loadedIds);
  const advertised = selected ? advertisedToolIds(selected) : [];
  const enabledTools = selected ? effectiveTools(selected) : [];
  const nameDraft = selected
    // eslint-disable-next-line security/detect-object-injection -- key is the selected Runner id
    ? (nameDrafts[selected.runnerId] ?? config.displayName ?? '')
    : '';
  const dirDraft = selected
    // eslint-disable-next-line security/detect-object-injection -- key is the selected Runner id
    ? (dirDrafts[selected.runnerId] || config.directories)
    : { masterDir: '', worktreeDir: '' };
  const nameDirty =
    selected && String(nameDraft).trim() !== String(config.displayName ?? '');

  const handleNameSave = () => {
    if (!selected || !nameDirty) return;
    const trimmed = String(nameDraft).trim();
    if (!trimmed) {
      setActionError('Runner name must not be blank.');
      return;
    }
    void saveConfig(selected.runnerId, { displayName: trimmed }, 'Runner name saved.').then(
      (ok) => {
        if (ok) {
          setNameDrafts((prev) => {
            const next = { ...prev };
            // eslint-disable-next-line security/detect-object-injection -- key is the selected Runner id
            delete next[selected.runnerId];
            return next;
          });
        }
      },
    );
  };

  const handleDirectorySave = (field) => {
    if (!selected) return;
    const confirmKey = `${selected.runnerId}:${field}`;
    if (dirConfirm !== confirmKey) {
      setDirConfirm(confirmKey);
      return;
    }
    const { ok, errors } = validateDirectories(dirDraft);
    // eslint-disable-next-line security/detect-object-injection -- field is a fixed directory key
    if (!ok && errors[field]) {
      setDirErrors((prev) => ({ ...prev, [confirmKey]: errors[field] }));
      return;
    }
    const value = String(dirDraft[field] || '').trim();
    void saveConfig(
      selected.runnerId,
      { directories: { [field]: value } },
      'Directory saved.',
    ).then((saved) => {
      if (saved) {
        setDirDrafts((prev) => {
          const next = { ...prev };
          // eslint-disable-next-line security/detect-object-injection -- key is the selected Runner id
          delete next[selected.runnerId];
          return next;
        });
        setDirConfirm(null);
        setDirErrors((prev) => {
          const next = { ...prev };
          // eslint-disable-next-line security/detect-object-injection -- confirm key for this Runner/field
          delete next[confirmKey];
          return next;
        });
      }
    });
  };

  const handleToolToggle = (toolId, checked) => {
    if (!selected) return;
    const next = checked
      ? [...new Set([...enabledTools, toolId])]
      : enabledTools.filter((t) => t !== toolId);
    void saveConfig(selected.runnerId, { availableTools: next }, 'Available tools saved.');
  };

  const handleJobToggle = (jobKey, checked) => {
    if (!selected) return;
    void saveConfig(
      selected.runnerId,
      { jobTypes: { [jobKey]: checked } },
      'Job type saved.',
    );
  };

  const handleProjectMove = (projectId, direction) => {
    if (!selected) return;
    const next =
      direction === 'load'
        ? withProjectLoaded(loadedIds, projectId)
        : withProjectUnloaded(loadedIds, projectId);
    void saveConfig(
      selected.runnerId,
      { projectScope: scopePatchForLoaded(next, projects || []) },
      direction === 'load' ? 'Project loaded.' : 'Project unloaded.',
    );
  };

  return (
    <section aria-label="Runner configuration" data-testid="runner-configuration-section">
      <h2 className="mt-6 text-lg font-bold uppercase tracking-tight text-text-high flex items-center gap-2 font-headline-md">
        Runners
      </h2>
      <p className="mt-2 text-xs text-text-muted">
        Out-of-process task executors (runner-only: every agent stage runs on
        a Runner). A Runner joins
        with the operator join token set as KAINBAIN_RUNNER_JOIN_TOKEN on the
        backend, waits here for approval, then heartbeats and claims tasks
        with its own credential. Select a Runner below to configure its name,
        projects, tools, directories, and job types.
      </p>
      {scheduler && (
        <p className="mt-1 text-[10px] font-mono text-text-muted" data-testid="runner-scheduler-deferrals">
          Scheduler: {scheduler.dispatched ?? 0} embedded dispatches,{' '}
          {scheduler.deferredDispatch ?? 0} deferred to Runners
          {scheduler.lastOutcome ? ` (last: ${scheduler.lastOutcome})` : ''}.
        </p>
      )}
      {actionError && (
        <p className="mt-2 text-xs text-error" role="alert">
          {actionError}
        </p>
      )}
      {notice && (
        <p className="mt-2 text-xs text-text-muted" role="status" data-testid="runner-config-notice">
          {notice}
        </p>
      )}
      {freshCredential && (
        <div
          className="mt-3 px-3 py-2 bg-surface-container border border-border-standard rounded-sm"
          data-testid="runner-credential-once"
        >
          <p className="text-xs text-on-surface">
            Runner {freshCredential.runnerId} approved. Paste this one-time
            credential into its environment as KAINBAIN_RUNNER_CREDENTIAL and
            restart it — it is never shown again.
          </p>
          <div className="mt-2 flex flex-wrap items-center gap-2">
            <span className="text-xs font-mono text-on-surface break-all" data-testid="runner-credential-value">
              {freshCredential.credential}
            </span>
            <button
              type="button"
              onClick={async () => {
                await copyToClipboard(freshCredential.credential);
                setCopied(true);
              }}
              className="px-3 py-1.5 min-h-[44px] bg-surface-container-high hover:bg-surface-container-highest text-on-surface-variant text-xs font-bold uppercase tracking-widest rounded-sm transition-colors cursor-pointer"
            >
              {copied ? 'Copied' : 'Copy'}
            </button>
            <button
              type="button"
              onClick={() => setFreshCredential(null)}
              aria-label="Dismiss credential"
              className="px-3 py-1.5 min-h-[44px] text-on-surface-variant text-xs font-bold uppercase tracking-widest rounded-sm transition-colors cursor-pointer"
            >
              Dismiss
            </button>
          </div>
        </div>
      )}
      {runners.length === 0 ? (
        <p className="py-4 text-xs text-text-muted" data-testid="runner-config-empty">
          No Runner registrations yet. Boot a Runner pointed at this backend and
          its join request will appear here.
        </p>
      ) : (
        <ul className="mt-3 flex flex-col gap-2" data-testid="runner-roster">
          {runners.map((runner) => {
            const isSelected = runner.runnerId === selectedId;
            const rowBusy = busyKey && busyKey.endsWith(`:${runner.runnerId}`);
            const assignment = assignments[runner.runnerId];
            return (
              <li
                key={runner.runnerId}
                data-testid={`runner-row-${runner.runnerId}`}
                className={`flex flex-wrap items-center gap-2 px-3 py-2 bg-surface-container border rounded-sm ${
                  isSelected ? 'border-primary' : 'border-border-standard'
                }`}
              >
                <button
                  type="button"
                  onClick={() => setSelectedId(runner.runnerId)}
                  aria-pressed={isSelected}
                  aria-label={`Configure runner ${runner.runnerId}`}
                  data-testid={`runner-select-${runner.runnerId}`}
                  className="text-xs font-mono text-on-surface underline decoration-dotted underline-offset-4 cursor-pointer"
                >
                  {runnerDisplayName(runner)}
                </button>
                <span
                  className="text-[10px] font-bold uppercase tracking-widest text-text-muted"
                  data-testid={`runner-status-${runner.runnerId}`}
                >
                  {runner.status}
                </span>
                {runner.status === 'active' && runner.paused && (
                  <span
                    className="text-[10px] font-bold uppercase tracking-widest text-warning"
                    data-testid={`runner-paused-${runner.runnerId}`}
                    title="Paused: this Runner finishes in-flight work but takes no new tasks"
                  >
                    paused
                  </span>
                )}
                {assignment && (
                  <span
                    className="text-[10px] font-mono text-text-muted"
                    data-testid={`runner-assignment-${runner.runnerId}`}
                  >
                    Running task {String(assignment.taskId).slice(0, 8)}
                    {' · '}
                    {assignment.stageId || '…'}
                    {' · '}
                    {nowMs == null
                      ? '…'
                      : formatRunnerElapsed(assignment.startedAt, nowMs)}
                  </span>
                )}
                {runner.facts?.versions?.runner && (
                  <span
                    className="text-[10px] font-mono text-text-muted"
                    data-testid={`runner-version-${runner.runnerId}`}
                  >
                    v{runner.facts.versions.runner}
                  </span>
                )}
                {runner.status === 'pending' ? (
                  <>
                    <button
                      type="button"
                      disabled={Boolean(rowBusy)}
                      onClick={() => mutate(runner.runnerId, 'approve')}
                      aria-label={`Approve runner ${runner.runnerId}`}
                      className="ml-auto px-3 py-1.5 min-h-[44px] bg-primary hover:brightness-110 text-on-primary text-xs font-bold uppercase tracking-widest rounded-sm transition-all cursor-pointer disabled:opacity-60"
                    >
                      Approve
                    </button>
                    <button
                      type="button"
                      disabled={Boolean(rowBusy)}
                      onClick={() => mutate(runner.runnerId, 'deny')}
                      aria-label={`Deny runner ${runner.runnerId}`}
                      className="px-3 py-1.5 min-h-[44px] bg-surface-container-high hover:bg-surface-container-highest text-on-surface-variant text-xs font-bold uppercase tracking-widest rounded-sm transition-colors cursor-pointer disabled:opacity-60"
                    >
                      Deny
                    </button>
                  </>
                ) : (
                  runner.status === 'active' && (
                    <>
                      {runner.paused ? (
                        <button
                          type="button"
                          disabled={Boolean(rowBusy)}
                          onClick={() => mutate(runner.runnerId, 'resume')}
                          aria-label={`Resume runner ${runner.runnerId}`}
                          className="px-3 py-1.5 min-h-[44px] bg-surface-container-high hover:bg-surface-container-highest text-on-surface-variant text-xs font-bold uppercase tracking-widest rounded-sm transition-colors cursor-pointer disabled:opacity-60"
                        >
                          Resume
                        </button>
                      ) : (
                        <button
                          type="button"
                          disabled={Boolean(rowBusy)}
                          onClick={() => mutate(runner.runnerId, 'pause')}
                          aria-label={`Pause runner ${runner.runnerId}`}
                          className="px-3 py-1.5 min-h-[44px] bg-surface-container-high hover:bg-surface-container-highest text-on-surface-variant text-xs font-bold uppercase tracking-widest rounded-sm transition-colors cursor-pointer disabled:opacity-60"
                        >
                          Pause
                        </button>
                      )}
                      <button
                        type="button"
                        disabled={Boolean(rowBusy)}
                        onClick={() => mutate(runner.runnerId, 'revoke')}
                        aria-label={`Revoke runner ${runner.runnerId}`}
                        className="ml-auto px-3 py-1.5 min-h-[44px] bg-surface-container-high hover:bg-surface-container-highest text-on-surface-variant text-xs font-bold uppercase tracking-widest rounded-sm transition-colors cursor-pointer disabled:opacity-60"
                      >
                        Revoke
                      </button>
                    </>
                  )
                )}
              </li>
            );
          })}
        </ul>
      )}
      {pending.length > 0 && (
        <p className="mt-2 text-xs text-text-muted" role="status">
          {pending.length} pending join request{pending.length === 1 ? '' : 's'}.
        </p>
      )}
      {selected && (
        <div
          className="mt-4 px-3 py-3 bg-surface-container border border-border-standard rounded-sm flex flex-col gap-4"
          data-testid={`runner-detail-${selected.runnerId}`}
        >
          <div className="flex items-center gap-2 flex-wrap">
            <h3 className="text-sm font-bold text-on-surface">
              {runnerDisplayName(selected)}
            </h3>
            <span
              className="text-[10px] font-bold uppercase tracking-widest text-text-muted"
              data-testid={`runner-detail-status-${selected.runnerId}`}
            >
              {selected.status === 'pending' ? 'Needs setup' : selected.status}
            </span>
            <button
              type="button"
              onClick={reloadSelected}
              disabled={busyKey === `reload:${selected.runnerId}`}
              data-testid={`runner-reload-${selected.runnerId}`}
              className="ml-auto px-3 py-1.5 min-h-[44px] bg-surface-container-high hover:bg-surface-container-highest text-on-surface-variant text-xs font-bold uppercase tracking-widest rounded-sm transition-colors cursor-pointer disabled:opacity-60"
            >
              Reload
            </button>
          </div>

          <div className="flex flex-col gap-1">
            <label
              className="text-xs font-bold text-on-surface"
              htmlFor={`runner-name-${selected.runnerId}`}
            >
              Runner Name:
            </label>
            <div className="flex items-center gap-2">
              <input
                id={`runner-name-${selected.runnerId}`}
                type="text"
                data-testid={`runner-name-${selected.runnerId}`}
                value={nameDraft}
                placeholder={selected.runnerId}
                onChange={(e) =>
                  setNameDrafts((prev) => ({
                    ...prev,
                    // eslint-disable-next-line security/detect-object-injection -- key is the selected Runner id
                    [selected.runnerId]: e.target.value,
                  }))
                }
                className="flex-1 min-w-0 max-w-sm p-2 bg-surface-deep border border-border-standard rounded-sm text-sm text-on-surface outline-none focus:border-primary transition-colors"
              />
              <button
                type="button"
                data-testid={`runner-name-save-${selected.runnerId}`}
                onClick={handleNameSave}
                disabled={!nameDirty || Boolean(busyKey)}
                className="px-3 py-2 min-h-[44px] bg-surface-container-high hover:bg-surface-container-highest text-on-surface-variant text-xs font-bold uppercase tracking-widest rounded-sm transition-colors cursor-pointer disabled:opacity-60 shrink-0"
              >
                Save
              </button>
            </div>
          </div>

          <div className="flex flex-col gap-1">
            <span className="text-xs font-bold text-on-surface" id={`projects-label-${selected.runnerId}`}>
              Projects
            </span>
            {projectsError ? (
              <p className="text-[11px] text-text-muted" data-testid="runner-projects-error">
                {projectsError}
              </p>
            ) : (
              <div
                className="grid grid-cols-2 gap-2"
                role="group"
                aria-labelledby={`projects-label-${selected.runnerId}`}
              >
                <div className="flex flex-col gap-1 px-2 py-2 bg-surface-deep border border-border-standard rounded-sm">
                  <span className="text-[11px] font-bold uppercase tracking-widest text-text-muted">
                    Available
                  </span>
                  {available.length === 0 && (
                    <span className="text-[11px] text-text-muted">None</span>
                  )}
                  {available.map((project) => (
                    <div key={project.id} className="flex items-center gap-2">
                      <span className="text-xs text-on-surface truncate">
                        {project.name || project.id}
                      </span>
                      <button
                        type="button"
                        data-testid={`runner-load-project-${project.id}`}
                        aria-label={`Load project ${project.name || project.id}`}
                        onClick={() => handleProjectMove(project.id, 'load')}
                        disabled={Boolean(busyKey)}
                        className="ml-auto text-xs text-primary underline underline-offset-2 cursor-pointer disabled:opacity-60"
                      >
                        Load →
                      </button>
                    </div>
                  ))}
                </div>
                <div className="flex flex-col gap-1 px-2 py-2 bg-surface-deep border border-border-standard rounded-sm">
                  <span className="text-[11px] font-bold uppercase tracking-widest text-text-muted">
                    Loaded
                  </span>
                  {loaded.length === 0 && (
                    <span className="text-[11px] text-text-muted">None</span>
                  )}
                  {loaded.map((project) => (
                    <div key={project.id} className="flex items-center gap-2">
                      <button
                        type="button"
                        data-testid={`runner-unload-project-${project.id}`}
                        aria-label={`Unload project ${project.name || project.id}`}
                        onClick={() => handleProjectMove(project.id, 'unload')}
                        disabled={Boolean(busyKey)}
                        className="text-xs text-primary underline underline-offset-2 cursor-pointer disabled:opacity-60"
                      >
                        ← Unload
                      </button>
                      <span className="text-xs text-on-surface truncate">
                        {project.name || project.id}
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            )}
            <p className="text-[11px] text-text-muted">
              Loading makes the project active for this Runner. Unloading parks
              it back to Available.
            </p>
          </div>

          <div className="flex flex-col gap-1">
            <span className="text-xs font-bold text-on-surface" id={`tools-label-${selected.runnerId}`}>
              Harnesses Available
            </span>
            {advertised.length === 0 ? (
              <p className="text-[11px] text-text-muted" data-testid="runner-tools-empty">
                This Runner has not advertised any tools yet.
              </p>
            ) : (
              <div
                className="flex items-center gap-4 flex-wrap"
                role="group"
                aria-labelledby={`tools-label-${selected.runnerId}`}
              >
                {advertised.map((toolId) => (
                  <label
                    key={toolId}
                    className="flex items-center gap-2 cursor-pointer select-none text-xs text-on-surface"
                  >
                    <input
                      type="checkbox"
                      data-testid={`runner-tool-${selected.runnerId}-${toolId}`}
                      checked={enabledTools.includes(toolId)}
                      onChange={(e) => handleToolToggle(toolId, e.target.checked)}
                      disabled={Boolean(busyKey)}
                      className="rounded-sm bg-surface-deep border-border-standard text-primary focus:ring-0 cursor-pointer"
                    />
                    <span>{toolId}</span>
                  </label>
                ))}
              </div>
            )}
          </div>

          <div className="flex flex-col gap-3">
            <DirectoryField
              label="Master directory:"
              testId={`runner-masterdir-${selected.runnerId}`}
              value={dirDraft.masterDir || ''}
              error={dirErrors[`${selected.runnerId}:masterDir`]}
              busy={Boolean(busyKey)}
              confirmArmed={dirConfirm === `${selected.runnerId}:masterDir`}
              onChange={(value) => {
                setDirConfirm(null);
                setDirDrafts((prev) => ({
                  ...prev,
                  // eslint-disable-next-line security/detect-object-injection -- key is the selected Runner id
                  [selected.runnerId]: {
                    masterDir: value,
                    worktreeDir: prev[selected.runnerId]?.worktreeDir ?? config.directories.worktreeDir,
                  },
                }));
              }}
              onSave={() => handleDirectorySave('masterDir')}
            />
            <DirectoryField
              label="Worktree directory:"
              testId={`runner-worktreedir-${selected.runnerId}`}
              value={dirDraft.worktreeDir || ''}
              error={dirErrors[`${selected.runnerId}:worktreeDir`]}
              busy={Boolean(busyKey)}
              confirmArmed={dirConfirm === `${selected.runnerId}:worktreeDir`}
              onChange={(value) => {
                setDirConfirm(null);
                setDirDrafts((prev) => ({
                  ...prev,
                  // eslint-disable-next-line security/detect-object-injection -- key is the selected Runner id
                  [selected.runnerId]: {
                    masterDir: prev[selected.runnerId]?.masterDir ?? config.directories.masterDir,
                    worktreeDir: value,
                  },
                }));
              }}
              onSave={() => handleDirectorySave('worktreeDir')}
            />
          </div>

          <div className="flex flex-col gap-1">
            <span className="text-xs font-bold text-on-surface" id={`jobs-label-${selected.runnerId}`}>
              Job types
            </span>
            <div
              className="flex items-center gap-4 flex-wrap"
              role="group"
              aria-labelledby={`jobs-label-${selected.runnerId}`}
            >
              {jobTypeLabels().map(({ key, label, hint }) => (
                <label
                  key={key}
                  title={hint}
                  className="flex items-center gap-2 cursor-pointer select-none text-xs text-on-surface"
                >
                  <input
                    type="checkbox"
                    data-testid={`runner-job-${selected.runnerId}-${key}`}
                    checked={config.jobTypes[key] === true}
                    onChange={(e) => handleJobToggle(key, e.target.checked)}
                    disabled={Boolean(busyKey)}
                    className="rounded-sm bg-surface-deep border-border-standard text-primary focus:ring-0 cursor-pointer"
                  />
                  <span>{label}</span>
                </label>
              ))}
            </div>
          </div>
        </div>
      )}
    </section>
  );
}

/***
 * MARK: runnerConfigHelpers
 * @description Pure helpers for the System Settings Runner configuration
 *   screen: normalizing the operator-owned config embedded in each Runner
 *   record, splitting projects into Available/Loaded columns, validating
 *   directory edits, and labelling the job-type switches. No network, no
 *   React — fully unit-testable.
 * @example partitionProjects([{id:'a'}], ['a']) => { available: [], loaded: [{id:'a'}] }
 ***/

export const JOB_TYPE_KEYS = ['runsCi', 'runsMerges', 'runsImpromptu'];

/***
 * MARK: jobTypeLabels
 * @description Labels and hints for the three job-type switches on the
 *   Runner screen. Meanings are pinned by survey Q5: CI runs CI stages,
 *   merges runs merges plus host git actions, impromptu runs
 *   retrospective/non-task calls.
 * @example jobTypeLabels() => [{ key: 'runsCi', label: 'Runs CI', hint: '…' }, …]
 ***/
export const jobTypeLabels = () => [
  { key: 'runsCi', label: 'Runs CI', hint: 'Runs CI stages' },
  { key: 'runsMerges', label: 'Runs merges', hint: 'Runs merges and host git actions' },
  {
    key: 'runsImpromptu',
    label: 'Runs Impromptu',
    hint: 'Runs retrospective / non task calls',
  },
];

/***
 * MARK: defaultRunnerConfig
 * @description Normalizes the operator-owned config for one Runner record
 *   (older backends may omit `operatorConfig` entirely). Nulls keep their
 *   backend meaning: no display name (fall back to the Runner id), all
 *   advertised tools, and all projects loaded.
 * @example defaultRunnerConfig({}) => { displayName: null, jobTypes: { runsCi: true, … }, … }
 * @param {Object} [runner={}] - Runner record, possibly with `operatorConfig`.
 * @returns {Object} Normalized operator configuration.
 ***/
export const defaultRunnerConfig = (runner = {}) => {
  const raw = runner && typeof runner === 'object' ? runner.operatorConfig : null;
  const source = raw && typeof raw === 'object' ? raw : {};
  const jobTypes = { runsCi: true, runsMerges: true, runsImpromptu: true };
  if (source.jobTypes && typeof source.jobTypes === 'object') {
    for (const key of JOB_TYPE_KEYS) {
      if (typeof source.jobTypes[key] === 'boolean') jobTypes[key] = source.jobTypes[key];
    }
  }
  const directories = { masterDir: '', worktreeDir: '' };
  if (source.directories && typeof source.directories === 'object') {
    for (const key of ['masterDir', 'worktreeDir']) {
      if (typeof source.directories[key] === 'string') directories[key] = source.directories[key];
    }
  }
  return {
    displayName: typeof source.displayName === 'string' ? source.displayName : null,
    availableTools: Array.isArray(source.availableTools)
      ? source.availableTools.filter((t) => typeof t === 'string')
      : null,
    jobTypes,
    directories,
    projectScope: Array.isArray(source.projectScope)
      ? source.projectScope.filter((p) => typeof p === 'string')
      : null,
  };
};

/***
 * MARK: runnerDisplayName
 * @description Operator-facing Runner name: the configured display name,
 *   falling back to the stable Runner id.
 * @example runnerDisplayName({ runnerId: 'r1', operatorConfig: null }) => 'r1'
 * @param {Object} [runner={}] - Runner record.
 * @returns {string} Display name.
 ***/
export const runnerDisplayName = (runner = {}) =>
  defaultRunnerConfig(runner).displayName || runner?.runnerId || '';

/***
 * MARK: advertisedToolIds
 * @description Harness/tool ids the Runner advertised in its capabilities.
 * @example advertisedToolIds({ capabilities: { harnesses: [{ id: 'pi' }] } }) => ['pi']
 * @param {Object} [runner={}] - Runner record.
 * @returns {string[]} Advertised ids (empty when unknown).
 ***/
export const advertisedToolIds = (runner = {}) => {
  const list = runner?.capabilities?.harnesses;
  if (!Array.isArray(list)) return [];
  return list
    .map((h) => (typeof h === 'string' ? h : h?.id))
    .filter((id) => typeof id === 'string' && id);
};

/***
 * MARK: effectiveTools
 * @description Tool ids enabled for the Runner: the operator subset when
 *   set, otherwise every advertised id.
 * @example effectiveTools({ capabilities: { harnesses: [{ id: 'pi' }] } }) => ['pi']
 * @param {Object} [runner={}] - Runner record.
 * @returns {string[]} Effective tool ids.
 ***/
export const effectiveTools = (runner = {}) => {
  const configured = defaultRunnerConfig(runner).availableTools;
  return Array.isArray(configured) ? configured : advertisedToolIds(runner);
};

/***
 * MARK: loadedProjectIds
 * @description Project ids in the Loaded column: the operator override when
 *   set, else the Runner-reported scope, else every known project (a null
 *   scope serves all projects).
 * @example loadedProjectIds({ projectScope: ['a'] }, [{ id: 'a' }, { id: 'b' }]) => ['a']
 * @param {Object} [runner={}] - Runner record.
 * @param {Object[]} [allProjects=[]] - All known projects (`{ id }`).
 * @returns {string[]} Loaded project ids.
 ***/
export const loadedProjectIds = (runner = {}, allProjects = []) => {
  const override = defaultRunnerConfig(runner).projectScope;
  if (Array.isArray(override)) return [...override];
  if (Array.isArray(runner?.projectScope) && runner.projectScope.length > 0) {
    return runner.projectScope.filter((p) => typeof p === 'string');
  }
  return (Array.isArray(allProjects) ? allProjects : [])
    .map((p) => p?.id)
    .filter((id) => typeof id === 'string');
};

/***
 * MARK: partitionProjects
 * @description Splits all projects into Available vs Loaded columns for the
 *   project picker. Unknown loaded ids (deleted projects) are dropped.
 * @example partitionProjects([{ id: 'a' }], ['a']) => { available: [], loaded: [{ id: 'a' }] }
 * @param {Object[]} [allProjects=[]] - All known projects (`{ id }`).
 * @param {string[]} [loadedIds=[]] - Loaded project ids.
 * @returns {{available: Object[], loaded: Object[]}} Column contents.
 ***/
export const partitionProjects = (allProjects = [], loadedIds = []) => {
  const ids = new Set(Array.isArray(loadedIds) ? loadedIds : []);
  const loaded = [];
  const available = [];
  for (const project of Array.isArray(allProjects) ? allProjects : []) {
    if (!project || typeof project.id !== 'string') continue;
    // eslint-disable-next-line security/detect-object-injection -- id is a project id from the project list response
    if (ids.has(project.id)) loaded.push(project);
    else available.push(project);
  }
  return { available, loaded };
};

/***
 * MARK: withProjectLoaded
 * @description Pure load move: returns the loaded id set with one project
 *   added (idempotent).
 * @example withProjectLoaded(['a'], 'b') => ['a', 'b']
 * @param {string[]} [loadedIds=[]] - Current loaded ids.
 * @param {string} projectId - Project id to load.
 * @returns {string[]} Next loaded ids.
 ***/
export const withProjectLoaded = (loadedIds = [], projectId) => {
  const next = [...(Array.isArray(loadedIds) ? loadedIds : [])];
  if (typeof projectId === 'string' && !next.includes(projectId)) next.push(projectId);
  return next;
};

/***
 * MARK: withProjectUnloaded
 * @description Pure unload move: returns the loaded id set with one project
 *   removed.
 * @example withProjectUnloaded(['a', 'b'], 'a') => ['b']
 * @param {string[]} [loadedIds=[]] - Current loaded ids.
 * @param {string} projectId - Project id to unload.
 * @returns {string[]} Next loaded ids.
 ***/
export const withProjectUnloaded = (loadedIds = [], projectId) =>
  (Array.isArray(loadedIds) ? loadedIds : []).filter((id) => id !== projectId);

/***
 * MARK: scopePatchForLoaded
 * @description Builds the `projectScope` patch for a loaded set: null when
 *   every known project is loaded (serves-all), otherwise the id list.
 * @example scopePatchForLoaded(['a'], [{ id: 'a' }, { id: 'b' }]) => ['a']
 * @param {string[]} [loadedIds=[]] - Loaded project ids.
 * @param {Object[]} [allProjects=[]] - All known projects (`{ id }`).
 * @returns {string[]|null} Patch value.
 ***/
export const scopePatchForLoaded = (loadedIds = [], allProjects = []) => {
  const loaded = new Set(Array.isArray(loadedIds) ? loadedIds : []);
  const all = (Array.isArray(allProjects) ? allProjects : [])
    .map((p) => p?.id)
    .filter((id) => typeof id === 'string');
  if (all.length > 0 && all.every((id) => loaded.has(id))) return null;
  return [...loaded];
};

/***
 * MARK: validateDirectories
 * @description Validates the Master/Worktree directory edits before save.
 *   Both fields are required and must be non-empty; values are never
 *   executed, only stored.
 * @example validateDirectories({ masterDir: '/srv/kb', worktreeDir: '' }) => { ok: false, errors: { worktreeDir: '…' } }
 * @param {Object} [directories={}] - Draft `{ masterDir, worktreeDir }`.
 * @returns {{ok: boolean, errors: Object}} Validation outcome.
 ***/
export const validateDirectories = (directories = {}) => {
  const errors = {};
  for (const key of ['masterDir', 'worktreeDir']) {
    const value = directories?.[key];
    if (typeof value !== 'string' || !value.trim()) {
      // eslint-disable-next-line security/detect-object-injection -- key is a fixed directory field name
      errors[key] = 'Enter a directory path.';
    }
  }
  return { ok: Object.keys(errors).length === 0, errors };
};

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import { RunnerConfigurationSection } from './RunnerConfigurationSection';

const getRunners = vi.hoisted(() => vi.fn());
const getRunnerMonitor = vi.hoisted(() => vi.fn());
const approveRunner = vi.hoisted(() => vi.fn());
const denyRunner = vi.hoisted(() => vi.fn());
const revokeRunner = vi.hoisted(() => vi.fn());
const pauseRunner = vi.hoisted(() => vi.fn());
const resumeRunner = vi.hoisted(() => vi.fn());
const listProjects = vi.hoisted(() => vi.fn());
const getRunnerConfig = vi.hoisted(() => vi.fn());
const updateRunnerConfig = vi.hoisted(() => vi.fn());

vi.mock('../../services/api', () => ({
  api: {
    getRunners,
    getRunnerMonitor,
    approveRunner,
    denyRunner,
    revokeRunner,
    pauseRunner,
    resumeRunner,
    listProjects,
    getRunnerConfig,
    updateRunnerConfig,
  },
}));

const OPERATOR_CONFIG = {
  displayName: null,
  availableTools: null,
  jobTypes: { runsCi: true, runsMerges: true, runsImpromptu: true },
  directories: { masterDir: '/srv/kb', worktreeDir: '/srv/kb-trees' },
  projectScope: null,
};

const ACTIVE_RUNNER = {
  runnerId: 'r1',
  status: 'active',
  facts: { versions: { runner: '0.3.0', protocol: 'v1' } },
  capabilities: { harnesses: [{ id: 'pi' }, { id: 'vibe' }] },
  projectScope: null,
  paused: false,
  lastSeenAt: null,
  operatorConfig: { ...OPERATOR_CONFIG },
};

const PENDING_RUNNER = {
  runnerId: 'r2',
  status: 'pending',
  facts: {},
  capabilities: null,
  projectScope: null,
  paused: false,
  lastSeenAt: null,
  operatorConfig: {
    displayName: null,
    availableTools: null,
    jobTypes: { runsCi: true, runsMerges: true, runsImpromptu: true },
    directories: { masterDir: '', worktreeDir: '' },
    projectScope: null,
  },
};

const PROJECTS = [
  { id: 'p1', name: 'Project One' },
  { id: 'p2', name: 'Project Two' },
];

/***
 * MARK: RunnerConfigurationSection tests
 * @description Covers the Runner settings screen that replaces the legacy
 *   harness list: roster loading/error/empty states, pending approve/deny,
 *   active pause/resume/revoke, the one-time credential, runner selection,
 *   and the detail form — name, Available/Loaded projects, tool toggles,
 *   directory save-with-confirm, job switches, and reload. Credentials
 *   never render.
 ***/
describe('RunnerConfigurationSection', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    getRunnerMonitor.mockResolvedValue({ liveAssignments: [] });
    listProjects.mockResolvedValue(PROJECTS);
    updateRunnerConfig.mockImplementation(async (id, patch) => ({
      runnerId: id,
      operatorConfig: { ...OPERATOR_CONFIG, ...patch },
    }));
  });

  function runnersFixture(rows = [ACTIVE_RUNNER, PENDING_RUNNER]) {
    getRunners.mockResolvedValue(structuredClone(rows));
  }

  it('shows loading then the empty state when no Runners registered', async () => {
    getRunners.mockResolvedValue([]);
    render(<RunnerConfigurationSection />);
    expect(screen.getByTestId('runner-config-loading')).toBeTruthy();
    await waitFor(() => {
      expect(screen.getByTestId('runner-config-empty')).toBeTruthy();
    });
    expect(screen.queryByTestId('runner-detail-r1')).toBeNull();
  });

  it('shows an error with retry when the list fetch fails', async () => {
    getRunners.mockRejectedValueOnce(new Error('backend down'));
    render(<RunnerConfigurationSection />);
    await waitFor(() => {
      expect(screen.getByTestId('runner-config-error')).toBeTruthy();
    });
    getRunners.mockResolvedValueOnce([]);
    fireEvent.click(screen.getByRole('button', { name: 'Retry' }));
    await waitFor(() => {
      expect(screen.getByTestId('runner-config-empty')).toBeTruthy();
    });
  });

  it('selects the first Runner and shows all five detail areas', async () => {
    runnersFixture([ACTIVE_RUNNER]);
    render(<RunnerConfigurationSection />);
    await waitFor(() => {
      expect(screen.getByTestId('runner-detail-r1')).toBeTruthy();
    });
    // 1. Runner name, 2. projects, 3. tools, 4. directories, 5. job switches.
    expect(screen.getByTestId('runner-name-r1')).toBeTruthy();
    expect(screen.getByText('Projects')).toBeTruthy();
    expect(screen.getByText('Harnesses Available')).toBeTruthy();
    expect(screen.getByTestId('runner-masterdir-r1')).toBeTruthy();
    expect(screen.getByTestId('runner-worktreedir-r1')).toBeTruthy();
    expect(screen.getByTestId('runner-job-r1-runsCi')).toBeTruthy();
    expect(screen.getByTestId('runner-job-r1-runsMerges')).toBeTruthy();
    expect(screen.getByTestId('runner-job-r1-runsImpromptu')).toBeTruthy();
    // Advertised tools render as toggles, all enabled by default.
    expect(screen.getByTestId('runner-tool-r1-pi')).toBeChecked();
    expect(screen.getByTestId('runner-tool-r1-vibe')).toBeChecked();
    // Null scope serves every project: all land in Loaded.
    expect(screen.getByTestId('runner-unload-project-p1')).toBeTruthy();
    expect(screen.getByTestId('runner-unload-project-p2')).toBeTruthy();
  });

  it('switches the detail form when another roster Runner is selected', async () => {
    runnersFixture();
    render(<RunnerConfigurationSection />);
    await screen.findByTestId('runner-detail-r1');
    fireEvent.click(screen.getByTestId('runner-select-r2'));
    await waitFor(() => {
      expect(screen.getByTestId('runner-detail-r2')).toBeTruthy();
    });
    expect(screen.getByTestId('runner-detail-status-r2')).toHaveTextContent('Needs setup');
    expect(screen.queryByTestId('runner-detail-r1')).toBeNull();
  });

  it('approves a pending Runner and shows the one-time credential once', async () => {
    runnersFixture([PENDING_RUNNER]);
    approveRunner.mockResolvedValue({ status: 'active', credential: 'ONE-TIME-1' });
    getRunners.mockResolvedValueOnce(structuredClone([PENDING_RUNNER]));
    render(<RunnerConfigurationSection />);
    fireEvent.click(await screen.findByRole('button', { name: 'Approve runner r2' }));
    await waitFor(() => {
      expect(approveRunner).toHaveBeenCalledWith('r2');
      expect(screen.getByTestId('runner-credential-once')).toBeTruthy();
    });
    expect(screen.getByTestId('runner-credential-value').textContent).toBe('ONE-TIME-1');
    fireEvent.click(screen.getByRole('button', { name: 'Dismiss credential' }));
    await waitFor(() => {
      expect(screen.queryByTestId('runner-credential-once')).toBeNull();
    });
  });

  it('denies a pending Runner and revokes an active one', async () => {
    runnersFixture();
    denyRunner.mockResolvedValue({ status: 'denied' });
    revokeRunner.mockResolvedValue({ status: 'revoked' });
    render(<RunnerConfigurationSection />);
    fireEvent.click(await screen.findByRole('button', { name: 'Deny runner r2' }));
    await waitFor(() => {
      expect(denyRunner).toHaveBeenCalledWith('r2');
    });
    fireEvent.click(await screen.findByRole('button', { name: 'Revoke runner r1' }));
    await waitFor(() => {
      expect(revokeRunner).toHaveBeenCalledWith('r1');
    });
  });

  it('pauses an active Runner and resumes a paused one', async () => {
    getRunners
      .mockResolvedValueOnce(structuredClone([{ ...ACTIVE_RUNNER, paused: false }]))
      .mockResolvedValueOnce(structuredClone([{ ...ACTIVE_RUNNER, paused: true }]))
      .mockResolvedValue(structuredClone([{ ...ACTIVE_RUNNER, paused: false }]));
    pauseRunner.mockResolvedValue({ status: 'active', paused: true });
    render(<RunnerConfigurationSection />);
    fireEvent.click(await screen.findByRole('button', { name: 'Pause runner r1' }));
    await waitFor(() => {
      expect(pauseRunner).toHaveBeenCalledWith('r1');
    });
    expect(screen.getByTestId('runner-paused-r1')).toBeTruthy();
    fireEvent.click(screen.getByRole('button', { name: 'Resume runner r1' }));
    await waitFor(() => {
      expect(resumeRunner).toHaveBeenCalledWith('r1');
    });
  });

  it('saves the Runner name', async () => {
    runnersFixture([ACTIVE_RUNNER]);
    render(<RunnerConfigurationSection />);
    await screen.findByTestId('runner-detail-r1');
    const input = screen.getByTestId('runner-name-r1');
    fireEvent.change(input, { target: { value: 'Primary' } });
    fireEvent.click(screen.getByTestId('runner-name-save-r1'));
    await waitFor(() => {
      expect(updateRunnerConfig).toHaveBeenCalledWith('r1', { displayName: 'Primary' });
    });
    expect(await screen.findByTestId('runner-config-notice')).toHaveTextContent(
      'Runner name saved.',
    );
  });

  it('loads and unloads projects through the picker', async () => {
    runnersFixture([{ ...ACTIVE_RUNNER, operatorConfig: { ...OPERATOR_CONFIG } }]);
    render(<RunnerConfigurationSection />);
    await screen.findByTestId('runner-detail-r1');
    // Both projects start Loaded (null scope serves all): unload one.
    fireEvent.click(screen.getByTestId('runner-unload-project-p1'));
    await waitFor(() => {
      expect(updateRunnerConfig).toHaveBeenCalledWith('r1', { projectScope: ['p2'] });
    });
  });

  it('loads an Available project back to Loaded with a null serves-all scope', async () => {
    runnersFixture([
      {
        ...ACTIVE_RUNNER,
        operatorConfig: { ...OPERATOR_CONFIG, projectScope: ['p2'] },
      },
    ]);
    render(<RunnerConfigurationSection />);
    await screen.findByTestId('runner-detail-r1');
    expect(screen.getByTestId('runner-load-project-p1')).toBeTruthy();
    fireEvent.click(screen.getByTestId('runner-load-project-p1'));
    await waitFor(() => {
      expect(updateRunnerConfig).toHaveBeenCalledWith('r1', { projectScope: null });
    });
  });

  it('requires confirmation before saving a directory', async () => {
    runnersFixture([ACTIVE_RUNNER]);
    render(<RunnerConfigurationSection />);
    await screen.findByTestId('runner-detail-r1');
    const input = screen.getByTestId('runner-masterdir-r1');
    fireEvent.change(input, { target: { value: ' /srv/new-master ' } });
    const save = screen.getByTestId('runner-masterdir-r1-save');
    // First click only arms the confirmation — no network call.
    fireEvent.click(save);
    expect(updateRunnerConfig).not.toHaveBeenCalled();
    expect(screen.getByTestId('runner-masterdir-r1-confirm')).toBeTruthy();
    // Second click confirms and trims.
    fireEvent.click(save);
    await waitFor(() => {
      expect(updateRunnerConfig).toHaveBeenCalledWith('r1', {
        directories: { masterDir: '/srv/new-master' },
      });
    });
  });

  it('blocks a blank directory save with an inline error and no network call', async () => {
    runnersFixture([ACTIVE_RUNNER]);
    render(<RunnerConfigurationSection />);
    await screen.findByTestId('runner-detail-r1');
    fireEvent.change(screen.getByTestId('runner-worktreedir-r1'), { target: { value: '   ' } });
    const save = screen.getByTestId('runner-worktreedir-r1-save');
    fireEvent.click(save);
    fireEvent.click(save);
    await waitFor(() => {
      expect(screen.getByTestId('runner-worktreedir-r1-error')).toBeTruthy();
    });
    expect(updateRunnerConfig).not.toHaveBeenCalled();
  });

  it('toggles job switches with the expected payload', async () => {
    runnersFixture([ACTIVE_RUNNER]);
    render(<RunnerConfigurationSection />);
    await screen.findByTestId('runner-detail-r1');
    fireEvent.click(screen.getByTestId('runner-job-r1-runsCi'));
    await waitFor(() => {
      expect(updateRunnerConfig).toHaveBeenCalledWith('r1', {
        jobTypes: { runsCi: false },
      });
    });
    fireEvent.click(screen.getByTestId('runner-job-r1-runsMerges'));
    await waitFor(() => {
      expect(updateRunnerConfig).toHaveBeenCalledWith('r1', {
        jobTypes: { runsMerges: false },
      });
    });
  });

  it('toggles an available tool off the Runner subset', async () => {
    runnersFixture([ACTIVE_RUNNER]);
    render(<RunnerConfigurationSection />);
    await screen.findByTestId('runner-detail-r1');
    fireEvent.click(screen.getByTestId('runner-tool-r1-vibe'));
    await waitFor(() => {
      expect(updateRunnerConfig).toHaveBeenCalledWith('r1', { availableTools: ['pi'] });
    });
  });

  it('reloads the selected Runner through getRunnerConfig', async () => {
    runnersFixture([ACTIVE_RUNNER]);
    getRunnerConfig.mockResolvedValue({
      ...ACTIVE_RUNNER,
      operatorConfig: { ...OPERATOR_CONFIG, displayName: 'Fresh' },
    });
    render(<RunnerConfigurationSection />);
    await screen.findByTestId('runner-detail-r1');
    fireEvent.click(screen.getByTestId('runner-reload-r1'));
    await waitFor(() => {
      expect(getRunnerConfig).toHaveBeenCalledWith('r1');
    });
    expect(await screen.findByTestId('runner-config-notice')).toHaveTextContent('Reloaded');
  });

  it('shows the live assignment under a running Runner', async () => {
    runnersFixture([ACTIVE_RUNNER]);
    getRunnerMonitor.mockResolvedValue({
      liveAssignments: [
        {
          runnerId: 'r1',
          projectId: 'p1',
          taskId: 'abcdef12-3456',
          executionId: 'exec-1',
          epoch: 1,
          startedAt: new Date(Date.now() - 65_000).toISOString(),
          stageId: 'build',
        },
      ],
    });
    render(<RunnerConfigurationSection />);
    await waitFor(() => {
      expect(screen.getByTestId('runner-assignment-r1').textContent).toContain('abcdef12');
    });
    expect(screen.getByTestId('runner-assignment-r1').textContent).toContain('build');
  });

  it('hides assignments but keeps the list when the monitor is down', async () => {
    runnersFixture([ACTIVE_RUNNER]);
    getRunnerMonitor.mockRejectedValueOnce(new Error('monitor down'));
    render(<RunnerConfigurationSection />);
    await screen.findByTestId('runner-detail-r1');
    expect(screen.queryByTestId('runner-assignment-r1')).toBeNull();
  });

  it('shows scheduler deferral counts when the monitor reports them', async () => {
    runnersFixture([ACTIVE_RUNNER]);
    getRunnerMonitor.mockResolvedValue({
      liveAssignments: [],
      scheduler: { ticks: 41, dispatched: 3, deferredDispatch: 12, deferredTripped: 0, lastOutcome: 'deferred-runner-dispatch', lastDispatchAt: null },
    });
    render(<RunnerConfigurationSection />);
    await waitFor(() => {
      expect(screen.getByTestId('runner-scheduler-deferrals').textContent).toContain(
        '12 deferred to Runners',
      );
    });
  });

  it('never renders credential values', async () => {
    runnersFixture([
      { ...ACTIVE_RUNNER, credential: 'SHOULD-NOT-RENDER' },
    ]);
    const { container } = render(<RunnerConfigurationSection />);
    await screen.findByTestId('runner-detail-r1');
    expect(container.textContent).not.toContain('SHOULD-NOT-RENDER');
  });

  it('shows the picker fallback when projects fail to load', async () => {
    runnersFixture([ACTIVE_RUNNER]);
    listProjects.mockRejectedValueOnce(new Error('projects down'));
    render(<RunnerConfigurationSection />);
    await waitFor(() => {
      expect(screen.getByTestId('runner-projects-error')).toBeTruthy();
    });
  });
});
